import { json, type LoaderFunctionArgs } from "react-router";
import db from "../db.server";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
} as const;

function parseSafe<T>(str: string, fallback: T): T {
  try { return JSON.parse(str) as T; } catch { return fallback; }
}

export async function loader({ request, params }: LoaderFunctionArgs) {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  const { slug } = params;
  const shop = new URL(request.url).searchParams.get("shop");

  if (!slug || !shop) {
    return json({ error: "Missing slug or shop parameter" }, { status: 400, headers: CORS_HEADERS });
  }

  // Validate shop domain format
  if (!/^[a-z0-9-]+\.myshopify\.com$/.test(shop)) {
    return json({ error: "Invalid shop domain" }, { status: 400, headers: CORS_HEADERS });
  }

  try {
    const quiz = await db.quiz.findFirst({
      where: { shop, slug, status: "active" },
      include: {
        questions: {
          include: { answers: { orderBy: { position: "asc" } } },
          orderBy: { position: "asc" },
        },
        resultPages: { orderBy: { position: "asc" } },
      },
    });

    if (!quiz) {
      return json({ error: "Quiz not found or not active" }, { status: 404, headers: CORS_HEADERS });
    }

    // Increment start count (fire and forget)
    db.quiz.update({ where: { id: quiz.id }, data: { startCount: { increment: 1 } } }).catch(() => {});

    return json({
      id: quiz.id,
      title: quiz.title,
      description: quiz.description,
      slug: quiz.slug,
      settings: parseSafe(quiz.settings, {}),
      styling: parseSafe(quiz.styling, {}),
      questions: quiz.questions.map((q) => ({
        id: q.id,
        type: q.type,
        title: q.title,
        description: q.description,
        imageUrl: q.imageUrl,
        required: q.required,
        position: q.position,
        settings: parseSafe(q.settings, {}),
        logic: parseSafe(q.logic, { rules: [] }),
        answers: q.answers.map((a) => ({
          id: a.id,
          text: a.text,
          imageUrl: a.imageUrl,
          position: a.position,
          score: a.score,
          productTags: parseSafe(a.productTags, [] as string[]),
        })),
      })),
      resultPages: quiz.resultPages.map((r) => ({
        id: r.id,
        title: r.title,
        description: r.description,
        type: r.type,
        minScore: r.minScore,
        maxScore: r.maxScore,
        matchTags: parseSafe(r.matchTags, [] as string[]),
        productLimit: r.productLimit,
        layout: r.layout,
        showDiscount: r.showDiscount,
        discountType: r.discountType,
        discountValue: r.discountValue,
        discountCode: r.discountCode,
        ctaText: r.ctaText,
        ctaUrl: r.ctaUrl,
      })),
    }, { headers: CORS_HEADERS });

  } catch (error) {
    console.error("Quiz API error:", error);
    return json({ error: "Internal server error" }, { status: 500, headers: CORS_HEADERS });
  }
}
