export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id!;
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");

  try {
    // Verify ownership first
    const quiz = await db.quiz.findFirst({ where: { id: quizId, shop: session.shop } });
    if (!quiz) return json({ error: "Quiz not found" }, { status: 404 });

    switch (intent) {
      case "save-design": {
        const title = String(formData.get("title") ?? "").trim();
        const description = String(formData.get("description") ?? "").trim() || null;
        const styling = String(formData.get("styling") ?? "{}");
        if (!title) return json({ error: "Title is required" });
        await db.quiz.update({ where: { id: quizId }, data: { title, description, styling, updatedAt: new Date() } });
        return json({ success: true, message: "Design saved!" });
      }
      case "publish": {
        await db.quiz.update({ where: { id: quizId }, data: { status: "active", publishedAt: quiz.publishedAt ?? new Date() } });
        return json({ success: true, message: "Quiz published! It's now live on your storefront." });
      }
      case "unpublish": {
        await db.quiz.update({ where: { id: quizId }, data: { status: "draft" } });
        return json({ success: true, message: "Quiz unpublished." });
      }
      case "delete": {
        await db.quiz.delete({ where: { id: quizId } });
        return redirect("/app/quizzes");
      }
      case "save-questions": {
        const questionsJson = String(formData.get("questions") ?? "[]");
        let questions: Array<{ id?: string; title: string; type: string; required: boolean; position: number; answers: Array<{ id?: string; text: string; score: number; productTags: string[]; position: number }> }>;
        try { questions = JSON.parse(questionsJson); } catch { return json({ error: "Invalid questions data" }); }

        // Delete all existing questions
        await db.question.deleteMany({ where: { quizId } });

        // Create new ones
        for (const q of questions) {
          await db.question.create({
            data: {
              quizId,
              title: q.title,
              type: q.type,
              required: q.required,
              position: q.position,
              answers: {
                create: q.answers.map(a => ({
                  text: a.text,
                  score: a.score,
                  productTags: JSON.stringify(a.productTags),
                  position: a.position,
                })),
              },
            },
          });
        }
        return json({ success: true, message: "Questions saved!" });
      }
      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    if (error instanceof Response) throw error;
    console.error(`Quiz action "${intent}" failed:`, error);
    return json({ error: "Action failed. Please try again." }, { status: 500 });
  }
};
