          discountCode: r.discountCode,
          ctaText: r.ctaText,
          ctaUrl: r.ctaUrl,
        })),
      },
      { headers: CORS_HEADERS },
    );
  } catch (error) {
    console.error("Quiz API error:", error);
    return json(
      { error: "Internal server error" },
      { status: 500, headers: CORS_HEADERS },
    );
