}

import { json, type ActionFunctionArgs, type LoaderFunctionArgs } from "react-router";
import db from "../db.server";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
} as const;

function parseSafe<T>(str: string, fallback: T): T {
  try {
    return JSON.parse(str) as T;
  } catch {
    return fallback;
  }
}

// Handle OPTIONS preflight — GET not allowed on this route
export async function loader({ request }: LoaderFunctionArgs) {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }
  return json(
    { error: "Method not allowed" },
    { status: 405, headers: CORS_HEADERS },
  );
}

interface SubmitAnswer {
  questionId: string;
  answerId?: string;
  value?: unknown;
}

interface SubmitBody {
  answers?: SubmitAnswer[];
  email?: string;
  sessionId?: string;
  source?: string;
  deviceType?: string;
}

export async function action({ request, params }: ActionFunctionArgs) {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  const { slug } = params;
  const shop = new URL(request.url).searchParams.get("shop");

  if (!slug || !shop) {
    return json(
      { error: "Missing slug or shop" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  // Validate shop domain format
  if (!/^[a-z0-9-]+\.myshopify\.com$/.test(shop)) {
    return json(
      { error: "Invalid shop domain" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  let body: SubmitBody;
  try {
    body = (await request.json()) as SubmitBody;
  } catch {
    return json(
      { error: "Invalid JSON body" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  try {
    const quiz = await db.quiz.findFirst({
      where: { shop, slug, status: "active" },
      include: {
        questions: {
          include: { answers: { orderBy: { position: "asc" } } },
          orderBy: { position: "asc" },
        },
        resultPages: { orderBy: { position: "asc" } },
      },
    });

    if (!quiz) {
      return json(
        { error: "Quiz not found" },
        { status: 404, headers: CORS_HEADERS },
      );
    }

    // Check monthly response limit against plan
    const startOfMonth = new Date();
    startOfMonth.setDate(1);
    startOfMonth.setHours(0, 0, 0, 0);

    const sub = await db.subscription.findUnique({
      where: { shop },
      select: { planId: true },
    });
    const planId = sub?.planId ?? "free";
    const limits: Record<string, number> = {
      free: 100,
      starter: 1000,
      pro: 10000,
      enterprise: 999999,
    };
    const responseLimit = limits[planId] ?? 100;
    const monthlyCount = await db.quizResponse.count({
      where: { shop, createdAt: { gte: startOfMonth } },
    });

    if (monthlyCount >= responseLimit) {
      return json(
        { error: "Response limit reached for this store" },
        { status: 429, headers: CORS_HEADERS },
      );
    }

    const answers = body.answers ?? [];
    const email = typeof body.email === "string" && body.email.trim() ? body.email.trim() : null;
    const sessionId =
      typeof body.sessionId === "string" && body.sessionId.trim()
        ? body.sessionId
        : crypto.randomUUID();

    // Calculate score and aggregate product tags
    let totalScore = 0;
    const productTagCounts: Record<string, number> = {};

    for (const answer of answers) {
      if (!answer.answerId) continue;
      const answerRecord = await db.answer.findUnique({
        where: { id: answer.answerId },
      });
      if (!answerRecord) continue;
      totalScore += answerRecord.score;
      const tags = parseSafe(answerRecord.productTags, [] as string[]);
      for (const tag of tags) {
        productTagCounts[tag] = (productTagCounts[tag] ?? 0) + 1;
      }
    }

    // Rank tags by frequency
    const topTags = Object.entries(productTagCounts)
      .sort(([, a], [, b]) => b - a)
      .map(([tag]) => tag);

    // Find the best matching result page
    let matchedResultPage =
      quiz.resultPages.find((rp) => {
        if (
          rp.type === "score-range" &&
          rp.minScore != null &&
          rp.maxScore != null
        ) {
          return totalScore >= rp.minScore && totalScore <= rp.maxScore;
        }
        if (rp.type === "tag-match") {
          const matchTags = parseSafe(rp.matchTags, [] as string[]);
          return topTags.some((tag) => matchTags.includes(tag));
        }
        return false;
      }) ?? quiz.resultPages[0];

    if (!matchedResultPage) {
      return json(
        { error: "No result pages configured for this quiz" },
        { status: 400, headers: CORS_HEADERS },
      );
    }

    // Fetch recommended products from synced catalog
    const topTagsList = topTags.slice(0, 5);
    const products =
      topTagsList.length > 0
        ? await db.productMapping.findMany({
            where: {
              shop,
              status: "active",
              OR: topTagsList.map((tag) => ({ tags: { contains: tag } })),
            },
            take: matchedResultPage.productLimit,
            orderBy: { score: "desc" },
          })
        : [];

    const recommendedProductGids = products.map((p) => p.productGid);

    // Persist the quiz response
    await db.quizResponse.create({
      data: {
        quizId: quiz.id,
        shop,
        sessionId,
        email,
        answers: JSON.stringify(answers),
        score: totalScore,
        recommendedProducts: JSON.stringify(recommendedProductGids),
        completedAt: new Date(),
        source: typeof body.source === "string" ? body.source : "embed",
        deviceType:
          typeof body.deviceType === "string" ? body.deviceType : null,
      },
    });

    // Increment quiz completion counter
    await db.quiz.update({
      where: { id: quiz.id },
      data: { completions: { increment: 1 } },
    });

    // Emit analytics event
    await db.analyticsEvent.create({
      data: {
        shop,
        quizId: quiz.id,
        eventType: "quiz_completed",
        sessionId,
        data: JSON.stringify({
          resultPageId: matchedResultPage.id,
          resultPageTitle: matchedResultPage.title,
          score: totalScore,
        }),
      },
    });

    // Sync email — fire and forget, never blocks the response
    if (email) {
      import("../services/email.server")
        .then(({ syncToEmailProvider }) => {
          syncToEmailProvider(shop, email, {
            quizTitle: quiz.title,
            quizSlug: quiz.slug,
            resultPageTitle: matchedResultPage!.title,
            score: totalScore,
            productTags: topTags,
          }).catch(console.error);
        })
        .catch(console.error);
    }

    return json(
      {
        sessionId,
        resultPage: {
          id: matchedResultPage.id,
          title: matchedResultPage.title,
          description: matchedResultPage.description,
          showDiscount: matchedResultPage.showDiscount,
          discountCode: matchedResultPage.discountCode,
          discountType: matchedResultPage.discountType,
          discountValue: matchedResultPage.discountValue,
          ctaText: matchedResultPage.ctaText,
          ctaUrl: matchedResultPage.ctaUrl,
          layout: matchedResultPage.layout,
        },
        score: totalScore,
        recommendedProducts: products.map((p) => ({
          gid: p.productGid,
          title: p.title,
          imageUrl: p.imageUrl,
          handle: p.handle,
          priceMin: p.priceMin,
          priceMax: p.priceMax,
        })),
      },
      { headers: CORS_HEADERS },
    );
  } catch (error) {
    console.error("Quiz submit error:", error);
    return json(
      { error: "Internal server error" },
      { status: 500, headers: CORS_HEADERS },
    );
  }
}

