// --- Loader ---

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id;

  if (!quizId) {
    throw json({ error: "Missing quiz ID" }, { status: 400 });
  }

  try {
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
      include: {
        questions: {
          include: { answers: { orderBy: { position: "asc" } } },
          orderBy: { position: "asc" },
        },
      },
    });

    if (!quiz) {
      throw json({ error: "Quiz not found" }, { status: 404 });
    }

    const stylingObj = parseSafe<{
      buttonColor?: string;
      buttonText?: string;
      resultsHeading?: string;
      showProgressBar?: boolean;
    }>(quiz.styling, {});

    const designSettings: DesignSettings = {
      quizTitle: quiz.title,
      description: quiz.description ?? "",
      buttonColor: stylingObj.buttonColor ?? "#5C6AC4",
      buttonText: stylingObj.buttonText ?? "Next",
      resultsHeading: stylingObj.resultsHeading ?? "Your Results",
      showProgressBar: stylingObj.showProgressBar ?? true,
    };

    const questions: Question[] = quiz.questions.map((q) => ({
      id: q.id,
      title: q.title,
      type: q.type,
      required: q.required,
      position: q.position,
      options: q.answers.map((a) => ({
        id: a.id,
        label: a.text,
        score: a.score,
        productTags: parseSafe(a.productTags, [] as string[]),
        position: a.position,
      })),
    }));

    return json<LoaderData>({
      quiz: {
        id: quiz.id,
        title: quiz.title,
        description: quiz.description,
        slug: quiz.slug,
        status: quiz.status,
        settings: quiz.settings,
        styling: quiz.styling,
      },
      questions,
      designSettings,
    });
  } catch (error) {
    if (error instanceof Response) throw error;
    throw json({ error: "Failed to load quiz" }, { status: 500 });
  }
};

// --- Action ---

export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id!;
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");

  try {
    // Verify ownership before any mutation
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
    });
    if (!quiz) {
      return json({ error: "Quiz not found" }, { status: 404 });
    }

    switch (intent) {
      case "save-design": {
        const title = String(formData.get("title") ?? "").trim();
        const description =
          String(formData.get("description") ?? "").trim() || null;
        const styling = String(formData.get("styling") ?? "{}");
        if (!title) {
          return json({ error: "Title is required" }, { status: 400 });
        }
        await db.quiz.update({
          where: { id: quizId },
          data: { title, description, styling, updatedAt: new Date() },
        });
        return json({ success: true, message: "Design saved!" });
      }

      case "publish": {
        await db.quiz.update({
          where: { id: quizId },
          data: {
            status: "active",
            publishedAt: quiz.publishedAt ?? new Date(),
          },
        });
        return json({
          success: true,
          message: "Quiz published! It's now live on your storefront.",
        });
      }

      case "unpublish": {
        await db.quiz.update({
          where: { id: quizId },
          data: { status: "draft" },
        });
        return json({ success: true, message: "Quiz unpublished." });
      }

      case "delete": {
        await db.quiz.delete({ where: { id: quizId } });
        return redirect("/app/quizzes");
      }

      case "save-questions": {
        const questionsJson = String(formData.get("questions") ?? "[]");
        let questions: Array<{
          id?: string;
          title: string;
          type: string;
          required: boolean;
          position: number;
          options: Array<{
            id?: string;
            label: string;
            score: number;
            productTags: string[];
            position: number;
          }>;
        }>;

        try {
          questions = JSON.parse(questionsJson);
        } catch {
          return json({ error: "Invalid questions data" }, { status: 400 });
        }

        // Delete all existing questions (cascade deletes answers)
        await db.question.deleteMany({ where: { quizId } });

        // Re-create all questions with their answers
        for (const q of questions) {
          await db.question.create({
            data: {
              quizId,
              title: q.title,
              type: q.type,
              required: q.required,
              position: q.position,
              answers: {
                create: q.options.map((a) => ({
                  text: a.label,
                  score: a.score,
                  productTags: JSON.stringify(a.productTags),
                  position: a.position,
                })),
              },
            },
          });
        }
        return json({ success: true, message: "Questions saved!" });
      }

      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    if (error instanceof Response) throw error;
    console.error(`Quiz action "${intent}" failed:`, error);
    return json(
      { error: "Action failed. Please try again." },
      { status: 500 },
    );
  }
};

