                />
              }
            />
            <TextField
              label="Button text"
              value={design.buttonText}
              onChange={(value) => onUpdateDesign("buttonText", value)}
              autoComplete="off"
            />
            <Divider />
            <Text as="h3" variant="headingSm" fontWeight="semibold">
              Results page
            </Text>
            <TextField
              label="Results page heading"
              value={design.resultsHeading}
              onChange={(value) => onUpdateDesign("resultsHeading", value)}
              autoComplete="off"
            />
            <Checkbox
              label="Show progress bar"
              checked={design.showProgressBar}
              onChange={(value) => onUpdateDesign("showProgressBar", value)}
            />
          </BlockStack>
        </Card>
      </Layout.Section>
      <Layout.Section variant="oneThird">
        <Card>
          <BlockStack gap="300">
            <Text as="h3" variant="headingSm" fontWeight="semibold">
              Preview
            </Text>
            <Divider />
            <div
              style={{
                border: "1px solid var(--p-color-border)",
                borderRadius: "var(--p-border-radius-300)",
                padding: 20,
                textAlign: "center",
              }}
            >
              <BlockStack gap="200">
                <Text as="p" variant="headingMd" fontWeight="bold">
                  {design.quizTitle || "Quiz Title"}
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  {design.description || "Quiz description goes here"}
                </Text>
                <div style={{ marginTop: 12 }}>
                  <div
                    style={{
                      display: "inline-block",
                      padding: "8px 24px",
                      borderRadius: 6,
                      backgroundColor: design.buttonColor,
                      color: "#fff",
                      fontSize: 14,
                      fontWeight: 600,
                    }}
                  >
                    {design.buttonText || "Next"}
                  </div>
                </div>
                {design.showProgressBar && (
                  <div
                    style={{
                      marginTop: 12,
                      height: 4,
                      borderRadius: 2,
                      background: "var(--p-color-bg-surface-secondary)",
                      overflow: "hidden",
                    }}
                  >
                    <div
                      style={{
                        width: "33%",
                        height: "100%",
                        borderRadius: 2,
                        background: design.buttonColor,
                      }}
                    />
                  </div>
                )}
              </BlockStack>
            </div>
          </BlockStack>
        </Card>
      </Layout.Section>
    </Layout>
  );
}

// --- Main Page ---

export default function QuizBuilder() {
  const loaderData = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigate = useNavigate();
  const submit = useSubmit();
  const shopify = useAppBridge();

  const { quiz, questions: initialQuestions, designSettings: initialDesign } =
    loaderData;

  const [questions, setQuestions] = useState<Question[]>(initialQuestions);
  const [selectedQuestionIndex, setSelectedQuestionIndex] = useState(0);
  const [design, setDesign] = useState<DesignSettings>(initialDesign);
  const [selectedTab, setSelectedTab] = useState(0);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);

  const quizId = quiz.id;

  // Show toast on every action result
  useEffect(() => {
    if (!actionData) return;
    if ("success" in actionData && actionData.success && "message" in actionData) {
      shopify.toast.show(String(actionData.message), { duration: 3000 });
    } else if ("error" in actionData && actionData.error) {
      shopify.toast.show(String(actionData.error), {
        duration: 4000,
        isError: true,
      });
    }
  }, [actionData, shopify]);

  const tabs = [
    { id: "questions", content: "Questions", panelID: "questions-panel" },
    { id: "mapping", content: "Product Mapping", panelID: "mapping-panel" },
    { id: "design", content: "Design", panelID: "design-panel" },
  ];

  const handleTabChange = useCallback((index: number) => {
    setSelectedTab(index);
  }, []);

  // Save questions tab
  const handleSaveQuestions = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "save-questions");
    formData.set(
      "questions",
      JSON.stringify(
        questions.map((q, qi) => ({
          id: q.id,
          title: q.title,
          type: q.type,
          required: q.required,
          position: qi,
          options: q.options.map((o, oi) => ({
            id: o.id,
            label: o.label,
            score: o.score,
            productTags: o.productTags,
            position: oi,
          })),
        })),
      ),
    );
    submit(formData, { method: "POST" });
  }, [questions, submit]);

  // Save design tab
  const handleSaveDesign = useCallback(() => {
    const stylingObj = {
      buttonColor: design.buttonColor,
      buttonText: design.buttonText,
      resultsHeading: design.resultsHeading,
      showProgressBar: design.showProgressBar,
    };
    const formData = new FormData();
    formData.set("intent", "save-design");
    formData.set("title", design.quizTitle);
    formData.set("description", design.description);
    formData.set("styling", JSON.stringify(stylingObj));
    submit(formData, { method: "POST" });
  }, [design, submit]);

  const handlePublish = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "publish");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handleUnpublish = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "unpublish");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handleDeleteConfirm = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "delete");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handlePreview = useCallback(() => {
    navigate(`/app/quizzes/${quizId}/preview`);
  }, [navigate, quizId]);

  const handleBack = useCallback(() => {
    navigate("/app/quizzes");
  }, [navigate]);

  // --- Question handlers ---

  const handleSelectQuestion = useCallback((index: number) => {
    setSelectedQuestionIndex(index);
  }, []);

  const handleUpdateQuestion = useCallback(
    (field: string, value: string | boolean) => {
      setQuestions((prev) => {
        const updated = [...prev];
        updated[selectedQuestionIndex] = {
          ...updated[selectedQuestionIndex],
          [field]: value,
        };
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleAddQuestion = useCallback(() => {
    const newId = `new-${Date.now()}`;
    const newQuestion: Question = {
      id: newId,
      title: "",
      type: "single",
      required: true,
      position: questions.length,
      options: [
        { id: `${newId}a1`, label: "Option 1", score: 0, productTags: [], position: 0 },
        { id: `${newId}a2`, label: "Option 2", score: 0, productTags: [], position: 1 },
      ],
    };
    setQuestions((prev) => [...prev, newQuestion]);
    setSelectedQuestionIndex(questions.length);
  }, [questions.length]);

  const handleAddOption = useCallback(() => {
    setQuestions((prev) => {
      const updated = [...prev];
      const question = { ...updated[selectedQuestionIndex] };
      const newOptionId = `${question.id}a${Date.now()}`;
      question.options = [
        ...question.options,
        {
          id: newOptionId,
          label: "",
          score: 0,
          productTags: [],
          position: question.options.length,
        },
      ];
      updated[selectedQuestionIndex] = question;
      return updated;
    });
  }, [selectedQuestionIndex]);

  const handleUpdateOption = useCallback(
    (optionId: string, value: string) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.options = question.options.map((opt) =>
          opt.id === optionId ? { ...opt, label: value } : opt,
        );
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleDeleteOption = useCallback(
    (optionId: string) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.options = question.options.filter(
          (opt) => opt.id !== optionId,
        );
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  // --- Product mapping handlers ---

  const handleAddProduct = useCallback(
    (questionId: string, optionId: string, tag: string) => {
      setQuestions((prev) =>
        prev.map((q) =>
          q.id === questionId
            ? {
                ...q,
                options: q.options.map((opt) =>
                  opt.id === optionId
                    ? {
                        ...opt,
                        productTags: [...opt.productTags, tag],
                      }
                    : opt,
                ),
              }
            : q,
        ),
      );
    },
    [],
  );

  const handleRemoveProduct = useCallback(
    (questionId: string, optionId: string, tag: string) => {
      setQuestions((prev) =>
        prev.map((q) =>
          q.id === questionId
            ? {
                ...q,
                options: q.options.map((opt) =>
                  opt.id === optionId
                    ? {
                        ...opt,
                        productTags: opt.productTags.filter((t) => t !== tag),
                      }
                    : opt,
                ),
              }
            : q,
        ),
      );
    },
    [],
  );

  // --- Design handlers ---

  const handleUpdateDesign = useCallback(
    (field: keyof DesignSettings, value: string | boolean) => {
      setDesign((prev) => ({ ...prev, [field]: value }));
    },
    [],
  );

  // Current save action depends on active tab
  const handleSave = useCallback(() => {
    if (selectedTab === 2) {
      handleSaveDesign();
    } else {
      handleSaveQuestions();
    }
  }, [selectedTab, handleSaveDesign, handleSaveQuestions]);

  const isLive = quiz.status === "active";
  const statusTone = isLive
    ? "success"
    : quiz.status === "draft"
      ? "attention"
      : undefined;
  const statusLabel = isLive ? "Live" : "Draft";

  return (
    <>
      <Page
        title={quiz.title}
        backAction={{ content: "Quizzes", onAction: handleBack }}
        titleMetadata={<Badge tone={statusTone}>{statusLabel}</Badge>}
        primaryAction={{
          content: "Save",
          onAction: handleSave,
        }}
        secondaryActions={[
          {
            content: "Preview",
            onAction: handlePreview,
          },
          isLive
            ? {
                content: "Unpublish",
                onAction: handleUnpublish,
              }
            : {
                content: "Publish",
                onAction: handlePublish,
              },
          {
            content: "Delete",
            destructive: true,
            onAction: () => setDeleteModalOpen(true),
          },
        ]}
      >
        <BlockStack gap="400">
          <Card padding="0">
            <Tabs tabs={tabs} selected={selectedTab} onSelect={handleTabChange}>
              <Box padding="400">
                {selectedTab === 0 && (
                  <QuestionsTab
                    questions={questions}
                    selectedQuestionIndex={selectedQuestionIndex}
                    onSelectQuestion={handleSelectQuestion}
                    onUpdateQuestion={handleUpdateQuestion}
                    onAddQuestion={handleAddQuestion}
                    onAddOption={handleAddOption}
                    onUpdateOption={handleUpdateOption}
                    onDeleteOption={handleDeleteOption}
                  />
                )}
                {selectedTab === 1 && (
                  <ProductMappingTab
                    questions={questions}
                    onAddProduct={handleAddProduct}
                    onRemoveProduct={handleRemoveProduct}
                  />
                )}
                {selectedTab === 2 && (
                  <DesignTab
                    design={design}
                    onUpdateDesign={handleUpdateDesign}
                  />
                )}
              </Box>
            </Tabs>
          </Card>
        </BlockStack>
      </Page>

      {/* Delete confirmation modal */}
      <Modal
        open={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        title="Delete quiz?"
        primaryAction={{
          content: "Delete",
          destructive: true,
          onAction: handleDeleteConfirm,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => setDeleteModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <Text as="p" variant="bodyMd">
            Are you sure you want to delete <strong>{quiz.title}</strong>? This
            will permanently delete the quiz, all its questions, answers, and
            response data. This action cannot be undone.
          </Text>
        </Modal.Section>
      </Modal>
    </>
  );
}

